import{_ as o}from"./chunks/infuse-files-favorites.ZRmFSxjS.js";import{_ as a}from"./chunks/infuse-custom-catalog-items.CH7-HJyD.js";import{_ as t,o as s,c as r,a2 as i}from"./chunks/framework.lxr64Vqo.js";const y=JSON.parse('{"title":"🍎 Infuse (Apple TV, iOS & Mac)","description":"","frontmatter":{},"headers":[],"relativePath":"clients/infuse.md","filePath":"clients/infuse.md","lastUpdated":1795112636000}'),n={name:"clients/infuse.md"};function l(d,e,c,u,h,m){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="🍎-infuse-apple-tv-ios-mac" tabindex="-1">🍎 Infuse (Apple TV, iOS &amp; Mac) <a class="header-anchor" href="#🍎-infuse-apple-tv-ios-mac" aria-label="Permalink to &quot;🍎 Infuse (Apple TV, iOS &amp; Mac)&quot;">​</a></h1><p>NoxMedia features native high-performance integration with <a href="https://firecore.com/infuse" target="_blank" rel="noreferrer">Firecore Infuse</a>, transforming your Telegram channels into an Apple-grade home theater experience.</p><p>With NoxMedia&#39;s <strong>Emulated Jellyfin Bridge</strong>, you get full DirectPlay capabilities, 4K HDR / Dolby Vision passthrough, Spatial Audio, and instant poster loading.</p><hr><h2 id="⚡-direct-mode-vs-library-mode" tabindex="-1">⚡ Direct Mode vs. Library Mode <a class="header-anchor" href="#⚡-direct-mode-vs-library-mode" aria-label="Permalink to &quot;⚡ Direct Mode vs. Library Mode&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Always use Direct Mode (Files browsing)</strong> for the best and fastest experience. In Infuse Settings → <strong>Library</strong>, do <strong>not</strong> enable full background indexing on the NoxMedia share. Infuse&#39;s standard Library mode attempts to recursively crawl every single item in one go, which can trigger network rate limits. Direct Mode streams metadata on-demand with <strong>0ms instant responses</strong>.</p></div><hr><h2 id="🛠️-step-by-step-setup-guide" tabindex="-1">🛠️ Step-by-Step Setup Guide <a class="header-anchor" href="#🛠️-step-by-step-setup-guide" aria-label="Permalink to &quot;🛠️ Step-by-Step Setup Guide&quot;">​</a></h2><h3 id="_1-find-your-noxmedia-server-ip" tabindex="-1">1. Find Your NoxMedia Server IP <a class="header-anchor" href="#_1-find-your-noxmedia-server-ip" aria-label="Permalink to &quot;1. Find Your NoxMedia Server IP&quot;">​</a></h3><ol><li>Open the NoxMedia app on your host device (Android phone or server).</li><li>Start the server toggle.</li><li>Note down the local IP displayed on the home dashboard (e.g., <code>http://192.168.1.15:8096</code>).</li></ol><h3 id="_2-add-jellyfin-share-in-infuse" tabindex="-1">2. Add Jellyfin Share in Infuse <a class="header-anchor" href="#_2-add-jellyfin-share-in-infuse" aria-label="Permalink to &quot;2. Add Jellyfin Share in Infuse&quot;">​</a></h3><ol><li>Open <strong>Infuse</strong> on your Apple TV, iPhone, iPad, or Mac.</li><li>Navigate to <strong>Settings</strong> (Gear icon) → <strong>Shares</strong> → <strong>Add Media...</strong></li><li>Under <em>Available Shares</em>, choose <strong>Other...</strong> or select <strong>Jellyfin</strong>.</li><li>Fill in the connection credentials: <ul><li><strong>Protocol</strong>: <code>Jellyfin</code> (or <code>Emby</code>)</li><li><strong>Address</strong>: <code>192.168.1.15</code> <em>(enter your device&#39;s actual IP)</em></li><li><strong>Port</strong>: <code>8096</code></li><li><strong>Username</strong>: <code>NoxMedia</code> <em>(or any username)</em></li><li><strong>Password</strong>: <em>(leave blank)</em></li></ul></li><li>Tap <strong>Save / Add</strong>. Infuse will connect to your NoxMedia server instantly.</li></ol><hr><h2 id="⭐-custom-shelves-home-screen-favorites" tabindex="-1">⭐ Custom Shelves &amp; Home Screen Favorites <a class="header-anchor" href="#⭐-custom-shelves-home-screen-favorites" aria-label="Permalink to &quot;⭐ Custom Shelves &amp; Home Screen Favorites&quot;">​</a></h2><p>NoxMedia&#39;s unique feature is exposing your <strong>AI-curated shelves and custom catalogs</strong> directly inside Infuse.</p><div class="screenshot-frame"><img src="'+o+'" alt="Infuse Files showing NoxMedia Custom Catalogs"><div class="screenshot-caption">Files view in Infuse displaying pinned Favorites and Custom Shelves like &quot;Murder Mystery Dark&quot;.</div></div><h3 id="how-to-pin-catalogs-to-your-home-screen" tabindex="-1">How to Pin Catalogs to your Home Screen: <a class="header-anchor" href="#how-to-pin-catalogs-to-your-home-screen" aria-label="Permalink to &quot;How to Pin Catalogs to your Home Screen:&quot;">​</a></h3><ol><li>Open Infuse and navigate to the <strong>Files</strong> tab.</li><li>Select your <strong>NoxMedia</strong> server.</li><li>You will see default libraries (<strong>Movies</strong>, <strong>TV Shows</strong>, <strong>Anime</strong>) alongside all your custom catalogs (e.g., <em>Murder Mystery Dark</em>, <em>Oscar Winners 2024</em>, <em>Anime Binge</em>).</li><li>Long-press (or tap the <strong>Star</strong> icon) on any custom shelf to mark it as a <strong>Favorite</strong>.</li><li>Once starred, it will appear directly on your Apple TV / iOS <strong>Home Screen carousel</strong> for one-click access!</li></ol><div class="screenshot-frame"><img src="'+a+'" alt="Infuse Custom Shelf Items Loaded with Posters"><div class="screenshot-caption">Inside the &quot;Murder Mystery Dark&quot; catalog with instant TMDB metadata, high-res posters, and release years.</div></div><hr><h2 id="🍿-playback-features" tabindex="-1">🍿 Playback Features <a class="header-anchor" href="#🍿-playback-features" aria-label="Permalink to &quot;🍿 Playback Features&quot;">​</a></h2><ul><li><strong>DirectPlay Everything</strong>: Infuse handles HEVC, AV1, VP9, H.264, DTS-HD, Dolby TrueHD, and EAC3 natively without server-side transcoding.</li><li><strong>Multiple Subtitles &amp; Audio Tracks</strong>: Switch between embedded Telegram audio streams and subtitle tracks on the fly.</li><li><strong>Dolby Vision &amp; HDR10+</strong>: Seamlessly mapped according to your Apple TV and display capabilities.</li></ul><hr><h2 id="🔍-troubleshooting" tabindex="-1">🔍 Troubleshooting <a class="header-anchor" href="#🔍-troubleshooting" aria-label="Permalink to &quot;🔍 Troubleshooting&quot;">​</a></h2><details><summary><b>Infuse shows a loading spinner on a catalog folder</b></summary><ol><li>Ensure the NoxMedia app on your host device is running and not put into deep sleep by Android&#39;s battery saver.</li><li>Check that both devices are connected to the same local Wi-Fi / subnet.</li><li>NoxMedia precomputes media catalogs in memory (<code>0ms cache</code>). If you just added a new channel or catalog, pull-down to refresh inside Infuse.</li></ol></details><details><summary><b>Poster artwork is missing for some items</b></summary><p>NoxMedia matches files using TMDB &amp; TVDB IDs. If a Telegram file doesn&#39;t have a clear filename, open NoxMedia on your phone, go to <strong>Index</strong>, and use <strong>Manual Match</strong> to assign the correct movie or show.</p></details>',26)])])}const b=t(n,[["render",l]]);export{y as __pageData,b as default};
